            {"id": "is-vip", "kind": "condition", "depends_on": [], "path": "customer.tier", "equals": "vip"},
            {"id": "gift", "kind": "task", "depends_on": ["is-vip"], "run_if": {"condition_id": "is-vip", "expected": True}},
            {"id": "receipt", "kind": "task", "depends_on": ["gift"]},
        ],
